import{check_activation}from"./utils.js";function Listing(){fetch("public-webp/episodes_list.json").then(e=>e.json()).then(e=>{const t=document.getElementById("chapter-list");Object.keys(e).reverse().forEach(e=>{const n=document.createElement("li"),c=document.createElement("a");let i=`lecture.html?path=${e}&page=1`;c.href=i,c.textContent=e,n.appendChild(c),t.appendChild(n)})}),check_activation("Listing")}Listing();